-- S4 núcleo LF: 25 CANDIDATAS de TRANSITIONS + OFFERS_INSTALLMENTS, 200 vectores.
-- Sin juicio, promoción, deprecación, cambio IG o edición de legadas.
BEGIN;
DO $pre$ BEGIN
 IF (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>94
  OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>0
  OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
  OR (SELECT count(*) FROM lf_ops.reglas) NOT IN (215,586)
  OR (SELECT count(distinct legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>75
 THEN RAISE EXCEPTION 'S4_BASELINE_DRIFT'; END IF;
END $pre$;
DO $s4$
