   THEN RAISE EXCEPTION 'S4_CREATE_FAIL % %',cd,q; END IF;
  IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
   OR (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
   THEN RAISE EXCEPTION 'S4_VECTORS_FAIL %',cd; END IF;
  hp:=lf_ops.nucleo_hash_paquete_v1(cd,1);
  IF length(hp)<>64 THEN RAISE EXCEPTION 'S4_HASH_FAIL %',cd; END IF;
  e:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
  IF e->>'decision'<>'BLOQUEADA' OR e->>'nota' IS NULL
   OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1)<>'CANDIDATA'
   THEN RAISE EXCEPTION 'S4_JUDGEMENT_GATE_FAIL % %',cd,e; END IF;
  n:=n+1;
  RAISE NOTICE 'S4_CANDIDATA % hash=% evaluated=%',cd,hp,e->>'decision';
 END LOOP;
 IF n<>25 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>25
  OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S4-C%')<>0
  OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S4-C%' AND estado='PUBLICADA')<>0
  OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
  OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM snap_legacy
  OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada x) IS DISTINCT FROM snap_bridge
  THEN RAISE EXCEPTION 'S4_FINAL_FAIL'; END IF;
 RAISE NOTICE 'S4_PASS candidatas=% vectors=200 no_juicios=true no_promocion=true',n;
END $s4$;
COMMIT;
